-- Generated by sample-data/build-demo-schema.py — the test version's own copy of the app in schema `demo`.
begin;
create schema if not exists demo;
grant usage on schema demo to anon, authenticated, service_role;
-- same default privileges Supabase gives the public schema; supabase.sql then revokes/grants on top, as it does there
alter default privileges in schema demo grant all on tables to anon, authenticated, service_role;
alter default privileges in schema demo grant all on sequences to anon, authenticated, service_role;
alter default privileges in schema demo grant all on functions to anon, authenticated, service_role;
set local search_path = demo;

-- King Crab House stock dashboard. Paste into Supabase → SQL Editor → Run.
-- Spoon measures are stored in tbsp (1 tbsp = 3 tsp); weights in grams; crab/egg in pieces.

create table if not exists ingredients (
  id    text primary key,
  name  text not null,
  unit  text not null,
  stock numeric not null default 0 check (stock >= 0)
);

create table if not exists recipes (
  id       text primary key,
  name     text not null,
  category text not null default 'platters' check (category in ('crab', 'platters', 'drinks'))
);

create table if not exists recipe_ingredients (
  recipe_id     text references recipes(id) on delete cascade,
  ingredient_id text references ingredients(id),
  qty           numeric not null check (qty > 0),
  primary key (recipe_id, ingredient_id)
);

alter table ingredients enable row level security;
alter table recipes enable row level security;
alter table recipe_ingredients enable row level security;

