create or replace function app_role() returns text language sql stable as $$
  select coalesce(auth.jwt() -> 'app_metadata' ->> 'role', '')
$$;

-- Order history. Written only by place_order(), readable by the page.
create table if not exists orders (
  id         bigint generated always as identity primary key,
  table_no   int not null check (table_no between 1 and 8),
  created_at timestamptz not null default now()
);
create table if not exists order_items (
  order_id  bigint references orders(id) on delete cascade,
  recipe_id text references recipes(id),
  qty       int not null check (qty > 0),
  primary key (order_id, recipe_id)
);
alter table orders enable row level security;
alter table order_items enable row level security;

-- Finish Order: records the order and deducts every ingredient in one transaction.
-- items = [{"recipe_id": "crab_rice", "qty": 2}, ...]. If any ingredient would go below 0,
-- the stock >= 0 check fails and nothing is saved or deducted.
-- security definer so the page can't insert orders directly without deducting stock.
drop function if exists place_order(jsonb);
drop function if exists place_order(text, jsonb);
create or replace function place_order(table_no int, items jsonb) returns bigint
language plpgsql security definer set search_path = demo as $$
declare new_id bigint;
begin
  if app_role() not in ('owner', 'staff') then
    raise exception 'Not signed in';
  end if;
  if table_no is null or table_no not between 1 and 8 then
    raise exception 'Pick a table';
  end if;
  if jsonb_typeof(items) <> 'array' or jsonb_array_length(items) = 0 then
    raise exception 'Order is empty';
  end if;
  if exists (select 1 from jsonb_array_elements(items) x
             where (x->>'qty') !~ '^[0-9]{1,4}$' or (x->>'qty')::int < 1
                or not exists (select 1 from recipes r where r.id = x->>'recipe_id')) then
    raise exception 'Invalid order item';
  end if;
  insert into orders (table_no) values (place_order.table_no) returning id into new_id;
  insert into order_items (order_id, recipe_id, qty)
    select new_id, x->>'recipe_id', sum((x->>'qty')::int) from jsonb_array_elements(items) x group by 2;
  update ingredients i set stock = i.stock - need.amt
  from (select ri.ingredient_id, sum(ri.qty * (x->>'qty')::int) amt
        from jsonb_array_elements(items) x
        join recipe_ingredients ri on ri.recipe_id = x->>'recipe_id'
        group by ri.ingredient_id) need
  where i.id = need.ingredient_id;
  return new_id;
exception when check_violation then
  raise exception 'Not enough stock for this order';
end $$;


-- ===== Access: sign-in required. Role comes from the user's app_metadata ("owner" or "staff"),
-- which only the Supabase dashboard/SQL can set, so a user can't promote themselves.
-- Signed-in users without a role get nothing.

revoke all on ingredients, recipes, recipe_ingredients, orders, order_items from anon;
revoke update, insert, delete on ingredients, recipes, recipe_ingredients, orders, order_items from authenticated;

-- staff and owner: read the menu and stock (staff need it to see what can still be ordered)
create policy "staff read ingredients" on ingredients for select to authenticated using (app_role() in ('owner', 'staff'));
create policy "staff read recipes" on recipes for select to authenticated using (app_role() in ('owner', 'staff'));
create policy "staff read recipe lines" on recipe_ingredients for select to authenticated using (app_role() in ('owner', 'staff'));
-- staff can only place orders (place_order below); owner only: history, stock counts, menu
create policy "owner read orders" on orders for select to authenticated using (app_role() = 'owner');
create policy "owner read order items" on order_items for select to authenticated using (app_role() = 'owner');
grant update (stock) on ingredients to authenticated;
create policy "owner update stock" on ingredients for update to authenticated
  using (app_role() = 'owner') with check (app_role() = 'owner');

-- owner only: Portions tab (menu items, recipe lines) and adding ingredients
grant insert (id, name, category) on recipes to authenticated;
create policy "owner add menu item" on recipes for insert to authenticated
  with check (app_role() = 'owner' and length(trim(name)) between 1 and 80);
grant insert (id, name, unit, stock) on ingredients to authenticated;
create policy "owner add ingredient" on ingredients for insert to authenticated
  with check (app_role() = 'owner' and length(trim(name)) between 1 and 80 and unit in ('pcs', 'g', 'tbsp'));
grant insert, delete on recipe_ingredients to authenticated;
grant update (qty) on recipe_ingredients to authenticated;
create policy "owner add recipe line" on recipe_ingredients for insert to authenticated with check (app_role() = 'owner');
create policy "owner edit recipe line" on recipe_ingredients for update to authenticated
  using (app_role() = 'owner') with check (app_role() = 'owner');
create policy "owner remove recipe line" on recipe_ingredients for delete to authenticated using (app_role() = 'owner');

revoke execute on function place_order(int, jsonb) from public, anon;
grant execute on function place_order(int, jsonb) to authenticated;

-- ===== Prices, costs and billing
-- recipes.price: menu price in pesos. ingredients.cost: pesos per unit (per g, pc or tbsp).
-- order_items.price: menu price at the time of ordering, so later price changes don't alter old bills.
-- orders.paid_at: null while the table's bill is open.
alter table recipes add column if not exists price numeric not null default 0 check (price >= 0);
alter table ingredients add column if not exists cost numeric not null default 0 check (cost >= 0);
alter table orders add column if not exists paid_at timestamptz;
alter table order_items add column if not exists price numeric;

