-- place_order now also records each item's current menu price
create or replace function place_order(table_no int, items jsonb) returns bigint
language plpgsql security definer set search_path = demo as $$
declare new_id bigint;
begin
  if app_role() not in ('owner', 'staff') then
    raise exception 'Not signed in';
  end if;
  if table_no is null or table_no not between 1 and 8 then
    raise exception 'Pick a table';
  end if;
  if jsonb_typeof(items) <> 'array' or jsonb_array_length(items) = 0 then
    raise exception 'Order is empty';
  end if;
  if exists (select 1 from jsonb_array_elements(items) x
             where (x->>'qty') !~ '^[0-9]{1,4}$' or (x->>'qty')::int < 1
                or not exists (select 1 from recipes r where r.id = x->>'recipe_id')) then
    raise exception 'Invalid order item';
  end if;
  insert into orders (table_no) values (place_order.table_no) returning id into new_id;
  insert into order_items (order_id, recipe_id, qty, price)
    select new_id, x->>'recipe_id', sum((x->>'qty')::int), max(r.price)
    from jsonb_array_elements(items) x join recipes r on r.id = x->>'recipe_id' group by 2;
  update ingredients i set stock = i.stock - need.amt
  from (select ri.ingredient_id, sum(ri.qty * (x->>'qty')::int) amt
        from jsonb_array_elements(items) x
        join recipe_ingredients ri on ri.recipe_id = x->>'recipe_id'
        group by ri.ingredient_id) need
  where i.id = need.ingredient_id;
  return new_id;
exception when check_violation then
  raise exception 'Not enough stock for this order';
end $$;

-- Billing: owner marks a table's open bill as paid; returns how many orders were closed.
create or replace function close_table(table_no int) returns int
language plpgsql security definer set search_path = demo as $$
declare n int;
begin
  if app_role() <> 'owner' then
    raise exception 'Only the owner can close bills';
  end if;
  update orders o set paid_at = now() where o.table_no = close_table.table_no and o.paid_at is null;
  get diagnostics n = row_count;
  return n;
end $$;
revoke execute on function close_table(int) from public, anon;
grant execute on function close_table(int) to authenticated;

-- owner edits menu prices (Portions) and ingredient costs (Inventory)
grant update (price) on recipes to authenticated;
create policy "owner edit menu price" on recipes for update to authenticated
  using (app_role() = 'owner') with check (app_role() = 'owner');
grant update (cost) on ingredients to authenticated;

-- ===== Daily profit: cost of one portion at the time of ordering, so later cost changes don't rewrite past profit
alter table order_items add column if not exists unit_cost numeric;

-- place_order also records each item's current menu price and ingredient cost per portion
create or replace function place_order(table_no int, items jsonb) returns bigint
language plpgsql security definer set search_path = demo as $$
declare new_id bigint;
begin
  if app_role() not in ('owner', 'staff') then
    raise exception 'Not signed in';
  end if;
  if table_no is null or table_no not between 1 and 8 then
    raise exception 'Pick a table';
  end if;
  if jsonb_typeof(items) <> 'array' or jsonb_array_length(items) = 0 then
    raise exception 'Order is empty';
  end if;
  if exists (select 1 from jsonb_array_elements(items) x
             where (x->>'qty') !~ '^[0-9]{1,4}$' or (x->>'qty')::int < 1
                or not exists (select 1 from recipes r where r.id = x->>'recipe_id')) then
    raise exception 'Invalid order item';
  end if;
  insert into orders (table_no) values (place_order.table_no) returning id into new_id;
  insert into order_items (order_id, recipe_id, qty, price, unit_cost)
    select new_id, r.id, sum((x->>'qty')::int), r.price,
           (select coalesce(sum(ri.qty * i.cost), 0) from recipe_ingredients ri join ingredients i on i.id = ri.ingredient_id where ri.recipe_id = r.id)
    from jsonb_array_elements(items) x join recipes r on r.id = x->>'recipe_id' group by r.id, r.price;
  update ingredients i set stock = i.stock - need.amt
  from (select ri.ingredient_id, sum(ri.qty * (x->>'qty')::int) amt
        from jsonb_array_elements(items) x
        join recipe_ingredients ri on ri.recipe_id = x->>'recipe_id'
        group by ri.ingredient_id) need
  where i.id = need.ingredient_id;
  return new_id;
exception when check_violation then
  raise exception 'Not enough stock for this order';
end $$;

-- ===== Costs live in owner-only tables; staff can see open bills and close them
create table if not exists ingredient_costs (
  ingredient_id text primary key references ingredients(id) on delete cascade,
  cost numeric not null default 0 check (cost >= 0)  -- pesos per g / pc / tbsp
);
create table if not exists order_item_costs (
  order_id  bigint references orders(id) on delete cascade,
  recipe_id text,
  unit_cost numeric not null,                         -- ingredient cost of one portion when ordered
  primary key (order_id, recipe_id)
);
insert into ingredient_costs (ingredient_id, cost) select id, cost from ingredients on conflict do nothing;
insert into order_item_costs (order_id, recipe_id, unit_cost)
  select order_id, recipe_id, unit_cost from order_items where unit_cost is not null on conflict do nothing;
alter table ingredients drop column if exists cost;
alter table order_items drop column if exists unit_cost;

alter table ingredient_costs enable row level security;
alter table order_item_costs enable row level security;
revoke all on ingredient_costs, order_item_costs from anon, authenticated;
grant select, insert, update on ingredient_costs to authenticated;
grant select on order_item_costs to authenticated;
create policy "owner read costs" on ingredient_costs for select to authenticated using (app_role() = 'owner');
create policy "owner add cost" on ingredient_costs for insert to authenticated with check (app_role() = 'owner');
create policy "owner edit cost" on ingredient_costs for update to authenticated using (app_role() = 'owner') with check (app_role() = 'owner');
create policy "owner read order costs" on order_item_costs for select to authenticated using (app_role() = 'owner');

-- staff see open (unpaid) orders for Billing; the owner sees all of them
drop policy if exists "owner read orders" on orders;
drop policy if exists "owner read order items" on order_items;
create policy "read orders" on orders for select to authenticated
  using (app_role() = 'owner' or (app_role() = 'staff' and paid_at is null));
create policy "read order items" on order_items for select to authenticated
  using (app_role() = 'owner' or (app_role() = 'staff' and exists (select 1 from orders o where o.id = order_id and o.paid_at is null)));

create or replace function place_order(table_no int, items jsonb) returns bigint
language plpgsql security definer set search_path = demo as $$
declare new_id bigint;
begin
  if app_role() not in ('owner', 'staff') then
    raise exception 'Not signed in';
  end if;
  if table_no is null or table_no not between 1 and 8 then
    raise exception 'Pick a table';
  end if;
  if jsonb_typeof(items) <> 'array' or jsonb_array_length(items) = 0 then
    raise exception 'Order is empty';
  end if;
  if exists (select 1 from jsonb_array_elements(items) x
             where (x->>'qty') !~ '^[0-9]{1,4}$' or (x->>'qty')::int < 1
                or not exists (select 1 from recipes r where r.id = x->>'recipe_id')) then
    raise exception 'Invalid order item';
  end if;
  insert into orders (table_no) values (place_order.table_no) returning id into new_id;
  insert into order_items (order_id, recipe_id, qty, price)
    select new_id, r.id, sum((x->>'qty')::int), r.price
    from jsonb_array_elements(items) x join recipes r on r.id = x->>'recipe_id' group by r.id, r.price;
  insert into order_item_costs (order_id, recipe_id, unit_cost)
    select new_id, oi.recipe_id,
           (select coalesce(sum(ri.qty * c.cost), 0) from recipe_ingredients ri
            left join ingredient_costs c on c.ingredient_id = ri.ingredient_id where ri.recipe_id = oi.recipe_id)
    from order_items oi where oi.order_id = new_id;
  update ingredients i set stock = i.stock - need.amt
  from (select ri.ingredient_id, sum(ri.qty * (x->>'qty')::int) amt
        from jsonb_array_elements(items) x
        join recipe_ingredients ri on ri.recipe_id = x->>'recipe_id'
        group by ri.ingredient_id) need
  where i.id = need.ingredient_id;
  return new_id;
exception when check_violation then
  raise exception 'Not enough stock for this order';
end $$;

-- staff take payments too
create or replace function close_table(table_no int) returns int
language plpgsql security definer set search_path = demo as $$
declare n int;
begin
  if app_role() not in ('owner', 'staff') then
    raise exception 'Not signed in';
  end if;
  update orders o set paid_at = now() where o.table_no = close_table.table_no and o.paid_at is null;
  get diagnostics n = row_count;
  return n;
end $$;

-- ===== Stock is added one purchase at a time; cost = average price paid across purchases
create table if not exists purchases (
  id            bigint generated always as identity primary key,
  ingredient_id text not null references ingredients(id) on delete cascade,
  qty           numeric not null check (qty > 0),           -- in the ingredient's unit (g / pcs / tbsp)
  total_cost    numeric not null check (total_cost >= 0),   -- pesos paid for that amount
  created_at    timestamptz not null default now(),
  created_by    uuid default auth.uid()
);
alter table purchases enable row level security;
revoke all on purchases from anon, authenticated;
grant select on purchases to authenticated;
create policy "owner read purchases" on purchases for select to authenticated using (app_role() = 'owner');

-- placeholder costs stay marked as estimates until the first real purchase
alter table ingredient_costs add column if not exists estimated boolean not null default true;

-- cost and stock now change only through add_purchase
drop policy if exists "owner add cost" on ingredient_costs;
drop policy if exists "owner edit cost" on ingredient_costs;
revoke insert, update on ingredient_costs from authenticated;
revoke update (stock) on ingredients from authenticated;
drop policy if exists "owner update stock" on ingredients;

create or replace function add_purchase(ingredient_id text, qty numeric, total_cost numeric) returns jsonb
language plpgsql security definer set search_path = demo as $$
declare new_stock numeric; avg_cost numeric;
begin
  if app_role() <> 'owner' then
    raise exception 'Only the owner can add stock';
  end if;
  if qty is null or qty <= 0 or total_cost is null or total_cost < 0 then
    raise exception 'Amount must be above 0 and cost 0 or more';
  end if;
  insert into purchases (ingredient_id, qty, total_cost) values (add_purchase.ingredient_id, qty, total_cost);
  update ingredients i set stock = i.stock + qty where i.id = add_purchase.ingredient_id returning i.stock into new_stock;
  if new_stock is null then
    raise exception 'Unknown ingredient';
  end if;
  select sum(p.total_cost) / sum(p.qty) into avg_cost from purchases p where p.ingredient_id = add_purchase.ingredient_id;
  insert into ingredient_costs (ingredient_id, cost, estimated) values (add_purchase.ingredient_id, avg_cost, false)
    on conflict on constraint ingredient_costs_pkey do update set cost = excluded.cost, estimated = false;
  return jsonb_build_object('stock', new_stock, 'cost', avg_cost);
end $$;
revoke execute on function add_purchase(text, numeric, numeric) from public, anon;
grant execute on function add_purchase(text, numeric, numeric) to authenticated;

-- ===== Stock corrections (waste, spoilage, miscount). Logged; average price paid is not affected.
create table if not exists stock_adjustments (
  id            bigint generated always as identity primary key,
  ingredient_id text not null references ingredients(id) on delete cascade,
  change        numeric not null,                 -- new count minus old count (negative = removed)
  new_stock     numeric not null check (new_stock >= 0),
  reason        text not null check (reason in ('waste', 'miscount', 'other')),
  created_at    timestamptz not null default now(),
  created_by    uuid default auth.uid()
);
alter table stock_adjustments enable row level security;
revoke all on stock_adjustments from anon, authenticated;
grant select on stock_adjustments to authenticated;
create policy "owner read adjustments" on stock_adjustments for select to authenticated using (app_role() = 'owner');

create or replace function adjust_stock(ingredient_id text, new_stock numeric, reason text) returns jsonb
language plpgsql security definer set search_path = demo as $$
declare old_stock numeric;
begin
  if app_role() <> 'owner' then
    raise exception 'Only the owner can correct stock';
  end if;
  if new_stock is null or new_stock < 0 then
    raise exception 'Count must be 0 or more';
  end if;
  if reason is null or reason not in ('waste', 'miscount', 'other') then
    raise exception 'Pick a reason';
  end if;
  select i.stock into old_stock from ingredients i where i.id = adjust_stock.ingredient_id for update;
  if old_stock is null then
    raise exception 'Unknown ingredient';
  end if;
  insert into stock_adjustments (ingredient_id, change, new_stock, reason)
    values (adjust_stock.ingredient_id, adjust_stock.new_stock - old_stock, adjust_stock.new_stock, adjust_stock.reason);
  update ingredients i set stock = adjust_stock.new_stock where i.id = adjust_stock.ingredient_id;
  return jsonb_build_object('stock', new_stock, 'change', new_stock - old_stock);
end $$;
revoke execute on function adjust_stock(text, numeric, text) from public, anon;
grant execute on function adjust_stock(text, numeric, text) to authenticated;

-- ===== Liquids and powders measured in mL instead of tbsp/tsp (1 tbsp = 15 mL, 1 tsp = 5 mL)
update recipe_ingredients ri set qty = round(ri.qty * 15, 4)
  from ingredients i where i.id = ri.ingredient_id and i.unit = 'tbsp';
update ingredient_costs c set cost = c.cost / 15
  from ingredients i where i.id = c.ingredient_id and i.unit = 'tbsp';
update purchases p set qty = p.qty * 15
  from ingredients i where i.id = p.ingredient_id and i.unit = 'tbsp';
update stock_adjustments a set change = a.change * 15, new_stock = a.new_stock * 15
  from ingredients i where i.id = a.ingredient_id and i.unit = 'tbsp';
update ingredients set stock = round(stock * 15, 4), unit = 'mL' where unit = 'tbsp';
drop policy if exists "owner add ingredient" on ingredients;
create policy "owner add ingredient" on ingredients for insert to authenticated
  with check (app_role() = 'owner' and length(trim(name)) between 1 and 80 and unit in ('pcs', 'g', 'mL'));

-- ===== Owner edits count and average price directly (pencil button); no reason needed.
-- Every edit is logged in stock_adjustments with old/new count and price.
alter table stock_adjustments alter column reason drop not null;
alter table stock_adjustments drop constraint if exists stock_adjustments_reason_check;
alter table stock_adjustments add column if not exists old_cost numeric;
alter table stock_adjustments add column if not exists new_cost numeric;
drop function if exists adjust_stock(text, numeric, text);

create or replace function edit_inventory(ingredient_id text, new_stock numeric, new_cost numeric) returns jsonb
language plpgsql security definer set search_path = demo as $$
declare old_stock numeric; old_cost numeric;
begin
  if app_role() <> 'owner' then
    raise exception 'Only the owner can edit inventory';
  end if;
  if new_stock is null or new_stock < 0 or new_cost is null or new_cost < 0 then
    raise exception 'Count and price must be 0 or more';
  end if;
  select i.stock into old_stock from ingredients i where i.id = edit_inventory.ingredient_id for update;
  if old_stock is null then
    raise exception 'Unknown ingredient';
  end if;
  select c.cost into old_cost from ingredient_costs c where c.ingredient_id = edit_inventory.ingredient_id;
  insert into stock_adjustments (ingredient_id, change, new_stock, old_cost, new_cost)
    values (edit_inventory.ingredient_id, edit_inventory.new_stock - old_stock, edit_inventory.new_stock, old_cost, edit_inventory.new_cost);
  update ingredients i set stock = edit_inventory.new_stock where i.id = edit_inventory.ingredient_id;
  insert into ingredient_costs (ingredient_id, cost, estimated) values (edit_inventory.ingredient_id, edit_inventory.new_cost, false)
    on conflict on constraint ingredient_costs_pkey do update set cost = excluded.cost, estimated = false;
  return jsonb_build_object('stock', new_stock, 'cost', new_cost);
end $$;
revoke execute on function edit_inventory(text, numeric, numeric) from public, anon;
grant execute on function edit_inventory(text, numeric, numeric) to authenticated;

-- Running (weighted) average: a purchase blends with what's on hand at the current average price,
-- so a price set by hand carries forward instead of being recalculated from all past purchases.
create or replace function add_purchase(ingredient_id text, qty numeric, total_cost numeric) returns jsonb
language plpgsql security definer set search_path = demo as $$
declare old_stock numeric; old_cost numeric; avg_cost numeric;
begin
  if app_role() <> 'owner' then
    raise exception 'Only the owner can add stock';
  end if;
  if qty is null or qty <= 0 or total_cost is null or total_cost < 0 then
    raise exception 'Amount must be above 0 and cost 0 or more';
  end if;
  select i.stock into old_stock from ingredients i where i.id = add_purchase.ingredient_id for update;
  if old_stock is null then
    raise exception 'Unknown ingredient';
  end if;
  select coalesce(c.cost, 0) into old_cost from ingredient_costs c where c.ingredient_id = add_purchase.ingredient_id;
  avg_cost := (greatest(old_stock, 0) * coalesce(old_cost, 0) + total_cost) / (greatest(old_stock, 0) + qty);
  insert into purchases (ingredient_id, qty, total_cost) values (add_purchase.ingredient_id, qty, total_cost);
  update ingredients i set stock = i.stock + qty where i.id = add_purchase.ingredient_id;
  insert into ingredient_costs (ingredient_id, cost, estimated) values (add_purchase.ingredient_id, avg_cost, false)
    on conflict on constraint ingredient_costs_pkey do update set cost = excluded.cost, estimated = false;
  return jsonb_build_object('stock', old_stock + qty, 'cost', avg_cost);
end $$;

-- ===== v2: bills & payments (method, change, Senior/PWD, service charge, split), order notes,
-- per-kg (market price) items, voids, low-stock levels, daily closing
alter table recipes add column if not exists pricing text not null default 'fixed' check (pricing in ('fixed', 'per_kg'));
grant update (pricing) on recipes to authenticated;  -- covered by the "owner edit menu price" policy
alter table order_items add column if not exists note text check (length(note) <= 120);
alter table ingredients add column if not exists min_stock numeric not null default 0 check (min_stock >= 0);

create table if not exists bills (
  id             bigint generated always as identity primary key,
  table_no       int not null,
  guests         int not null check (guests >= 1),
  seniors        int not null default 0 check (seniors >= 0),
  gross          numeric not null,              -- menu prices, VAT-inclusive
  vat_removed    numeric not null default 0,    -- VAT exemption on the Senior/PWD share
  discount       numeric not null default 0,    -- 20% Senior/PWD discount
  service_charge numeric not null default 0,
  total          numeric not null,
  closed_at      timestamptz not null default now(),
  created_by     uuid default auth.uid(),
  check (seniors <= guests)
);
create table if not exists payments (
  id         bigint generated always as identity primary key,
  bill_id    bigint not null references bills(id) on delete cascade,
  method     text not null check (method in ('cash', 'gcash', 'card')),
  amount     numeric not null check (amount >= 0),
  received   numeric not null,
  change     numeric not null default 0,
  created_at timestamptz not null default now()
);
alter table orders add column if not exists bill_id bigint references bills(id);
create table if not exists voids (
  id         bigint generated always as identity primary key,
  table_no   int not null,
  recipe_id  text not null,
  qty        int not null,
  price      numeric,
  created_at timestamptz not null default now(),
  created_by uuid default auth.uid()
);
create table if not exists day_closings (
  id            bigint generated always as identity primary key,
  day           date not null unique,
  expected_cash numeric not null,
  counted_cash  numeric not null,
  difference    numeric not null,
  summary       jsonb not null,
  created_at    timestamptz not null default now(),
  created_by    uuid default auth.uid()
);
alter table bills enable row level security;
alter table payments enable row level security;
alter table voids enable row level security;
alter table day_closings enable row level security;
revoke all on bills, payments, voids, day_closings from anon, authenticated;
grant select on bills, payments, voids, day_closings to authenticated;
create policy "owner read bills" on bills for select to authenticated using (app_role() = 'owner');
create policy "owner read payments" on payments for select to authenticated using (app_role() = 'owner');
create policy "owner read voids" on voids for select to authenticated using (app_role() = 'owner');
create policy "owner read closings" on day_closings for select to authenticated using (app_role() = 'owner');

-- place_order: optional note per item; per-kg items need the weight and are priced by it
create or replace function place_order(table_no int, items jsonb) returns bigint
language plpgsql security definer set search_path = demo as $$
declare new_id bigint;
begin
  if app_role() not in ('owner', 'staff') then
    raise exception 'Not signed in';
  end if;
  if table_no is null or table_no not between 1 and 8 then
    raise exception 'Pick a table';
  end if;
  if jsonb_typeof(items) <> 'array' or jsonb_array_length(items) = 0 then
    raise exception 'Order is empty';
  end if;
  if exists (select 1 from jsonb_array_elements(items) x
             where (x->>'qty') !~ '^[0-9]{1,4}$' or (x->>'qty')::int < 1
                or coalesce(x->>'weight', '') !~ '^([0-9]{1,3}(\.[0-9]{1,3})?)?$'
                or not exists (select 1 from recipes r where r.id = x->>'recipe_id')) then
    raise exception 'Invalid order item';
  end if;
  if exists (select 1 from jsonb_array_elements(items) x join recipes r on r.id = x->>'recipe_id'
             where r.pricing = 'per_kg' and coalesce(nullif(x->>'weight', '')::numeric, 0) <= 0) then
    raise exception 'Enter the weight for market-price items';
  end if;
  insert into orders (table_no) values (place_order.table_no) returning id into new_id;
  insert into order_items (order_id, recipe_id, qty, price, note)
    select new_id, r.id, sum((x->>'qty')::int),
           case when r.pricing = 'per_kg' then r.price * sum(nullif(x->>'weight', '')::numeric) / sum((x->>'qty')::int) else r.price end,
           left(string_agg(nullif(trim(x->>'note'), ''), '; '), 120)
    from jsonb_array_elements(items) x join recipes r on r.id = x->>'recipe_id' group by r.id, r.price, r.pricing;
  insert into order_item_costs (order_id, recipe_id, unit_cost)
    select new_id, oi.recipe_id,
           (select coalesce(sum(ri.qty * c.cost), 0) from recipe_ingredients ri
            left join ingredient_costs c on c.ingredient_id = ri.ingredient_id where ri.recipe_id = oi.recipe_id)
    from order_items oi where oi.order_id = new_id;
  update ingredients i set stock = i.stock - need.amt
  from (select ri.ingredient_id, sum(ri.qty * (x->>'qty')::int) amt
        from jsonb_array_elements(items) x
        join recipe_ingredients ri on ri.recipe_id = x->>'recipe_id'
        group by ri.ingredient_id) need
  where i.id = need.ingredient_id;
  return new_id;
exception when check_violation then
  raise exception 'Not enough stock for this order';
end $$;

-- close_table: works out the bill (same formula as billTotals in calc.js) and records the payments.
-- Senior/PWD: their share (seniors/guests of the bill) is VAT-exempt (price / 1.12) and then 20% off.
drop function if exists close_table(int);
create or replace function close_table(table_no int, guests int, seniors int, service_rate numeric, payments jsonb) returns jsonb
language plpgsql security definer set search_path = demo as $$
declare g numeric; share numeric; vat numeric; disc numeric; svc numeric; tot numeric; paid numeric; bid bigint;
begin
  if app_role() not in ('owner', 'staff') then
    raise exception 'Not signed in';
  end if;
  if guests is null or guests < 1 or guests > 50 or seniors is null or seniors < 0 or seniors > guests then
    raise exception 'Check the number of guests and Senior/PWD';
  end if;
  if service_rate is null or service_rate < 0 or service_rate > 0.2 then
    raise exception 'Invalid service charge';
  end if;
  select sum(oi.qty * oi.price) into g from orders o join order_items oi on oi.order_id = o.id
    where o.table_no = close_table.table_no and o.paid_at is null;
  if g is null then
    raise exception 'No open bill for this table';
  end if;
  share := g * seniors / guests;
  vat   := round(share - share / 1.12, 2);
  disc  := round(share / 1.12 * 0.20, 2);
  svc   := round((g - vat - disc) * service_rate, 2);
  tot   := round(g - vat - disc + svc, 2);
  if jsonb_typeof(payments) <> 'array' or jsonb_array_length(payments) not between 1 and 20 then
    raise exception 'Add at least one payment';
  end if;
  if exists (select 1 from jsonb_array_elements(payments) p
             where coalesce(p->>'method', '') not in ('cash', 'gcash', 'card')
                or coalesce(p->>'amount', '') !~ '^[0-9]+(\.[0-9]{1,2})?$'
                or (p->>'method' = 'cash' and coalesce(p->>'received', '') !~ '^[0-9]+(\.[0-9]{1,2})?$')) then
    raise exception 'Invalid payment';
  end if;
  if exists (select 1 from jsonb_array_elements(payments) p
             where p->>'method' = 'cash' and (p->>'received')::numeric < (p->>'amount')::numeric) then
    raise exception 'Cash received is less than the amount';
  end if;
  select sum((p->>'amount')::numeric) into paid from jsonb_array_elements(payments) p;
  if abs(paid - tot) > 0.05 then
    raise exception 'Payments add up to % but the bill is %', paid, tot;
  end if;
  insert into bills (table_no, guests, seniors, gross, vat_removed, discount, service_charge, total)
    values (close_table.table_no, guests, seniors, g, vat, disc, svc, tot) returning id into bid;
  insert into payments (bill_id, method, amount, received, change)
    select bid, p->>'method', (p->>'amount')::numeric,
           case when p->>'method' = 'cash' then (p->>'received')::numeric else (p->>'amount')::numeric end,
           case when p->>'method' = 'cash' then (p->>'received')::numeric - (p->>'amount')::numeric else 0 end
    from jsonb_array_elements(payments) p;
  update orders o set paid_at = now(), bill_id = bid where o.table_no = close_table.table_no and o.paid_at is null;
  return jsonb_build_object('bill_id', bid, 'gross', g, 'vat_removed', vat, 'discount', disc, 'service_charge', svc, 'total', tot);
end $$;
revoke execute on function close_table(int, int, int, numeric, jsonb) from public, anon;
grant execute on function close_table(int, int, int, numeric, jsonb) to authenticated;

-- void_item: take items off a table's open bill (newest first) and put their ingredients back in stock
create or replace function void_item(table_no int, recipe_id text, qty int) returns int
language plpgsql security definer set search_path = demo as $$
declare left_to_void int := qty; take int; r record;
begin
  if app_role() not in ('owner', 'staff') then
    raise exception 'Not signed in';
  end if;
  if qty is null or qty < 1 then
    raise exception 'Nothing to void';
  end if;
  if (select coalesce(sum(oi.qty), 0) from orders o join order_items oi on oi.order_id = o.id
      where o.table_no = void_item.table_no and o.paid_at is null and oi.recipe_id = void_item.recipe_id) < qty then
    raise exception 'That many are not on the bill';
  end if;
  for r in select oi.order_id, oi.qty, oi.price from orders o join order_items oi on oi.order_id = o.id
           where o.table_no = void_item.table_no and o.paid_at is null and oi.recipe_id = void_item.recipe_id
           order by o.created_at desc loop
    exit when left_to_void = 0;
    take := least(left_to_void, r.qty);
    if take = r.qty then
      delete from order_items oi where oi.order_id = r.order_id and oi.recipe_id = void_item.recipe_id;
      delete from order_item_costs c where c.order_id = r.order_id and c.recipe_id = void_item.recipe_id;
    else
      update order_items oi set qty = oi.qty - take where oi.order_id = r.order_id and oi.recipe_id = void_item.recipe_id;
    end if;
    insert into voids (table_no, recipe_id, qty, price) values (void_item.table_no, void_item.recipe_id, take, r.price);
    left_to_void := left_to_void - take;
  end loop;
  update ingredients i set stock = i.stock + ri.qty * void_item.qty
    from recipe_ingredients ri where ri.recipe_id = void_item.recipe_id and i.id = ri.ingredient_id;
  delete from orders o where o.table_no = void_item.table_no and o.paid_at is null
    and not exists (select 1 from order_items oi where oi.order_id = o.id);
  return qty;
end $$;
revoke execute on function void_item(int, text, int) from public, anon;
grant execute on function void_item(int, text, int) to authenticated;

-- edit_inventory now also sets the low-stock level (null = leave it)
drop function if exists edit_inventory(text, numeric, numeric);
create or replace function edit_inventory(ingredient_id text, new_stock numeric, new_cost numeric, new_min numeric default null) returns jsonb
language plpgsql security definer set search_path = demo as $$
declare old_stock numeric; old_cost numeric;
begin
  if app_role() <> 'owner' then
    raise exception 'Only the owner can edit inventory';
  end if;
  if new_stock is null or new_stock < 0 or new_cost is null or new_cost < 0 or new_min < 0 then
    raise exception 'Count, price and low-stock level must be 0 or more';
  end if;
  select i.stock into old_stock from ingredients i where i.id = edit_inventory.ingredient_id for update;
  if old_stock is null then
    raise exception 'Unknown ingredient';
  end if;
  select c.cost into old_cost from ingredient_costs c where c.ingredient_id = edit_inventory.ingredient_id;
  if new_stock <> old_stock or new_cost is distinct from old_cost then
    insert into stock_adjustments (ingredient_id, change, new_stock, old_cost, new_cost)
      values (edit_inventory.ingredient_id, edit_inventory.new_stock - old_stock, edit_inventory.new_stock, old_cost, edit_inventory.new_cost);
  end if;
  update ingredients i set stock = edit_inventory.new_stock, min_stock = coalesce(edit_inventory.new_min, i.min_stock)
    where i.id = edit_inventory.ingredient_id;
  insert into ingredient_costs (ingredient_id, cost, estimated) values (edit_inventory.ingredient_id, edit_inventory.new_cost, false)
    on conflict on constraint ingredient_costs_pkey do update set cost = excluded.cost, estimated = false;
  return jsonb_build_object('stock', new_stock, 'cost', new_cost, 'min_stock', (select min_stock from ingredients where id = edit_inventory.ingredient_id));
end $$;
revoke execute on function edit_inventory(text, numeric, numeric, numeric) from public, anon;
grant execute on function edit_inventory(text, numeric, numeric, numeric) to authenticated;

-- close_day: today's (Manila) takings vs. the cash counted in the drawer. Re-closing a day overwrites it.
create or replace function close_day(counted_cash numeric) returns jsonb
language plpgsql security definer set search_path = demo as $$
declare d date := (now() at time zone 'Asia/Manila')::date; s jsonb; expected numeric; row day_closings;
begin
  if app_role() <> 'owner' then
    raise exception 'Only the owner can close the day';
  end if;
  if counted_cash is null or counted_cash < 0 then
    raise exception 'Enter the cash counted';
  end if;
  select jsonb_build_object(
      'bills', (select count(*) from bills b where (b.closed_at at time zone 'Asia/Manila')::date = d),
      'gross', (select coalesce(sum(b.gross), 0) from bills b where (b.closed_at at time zone 'Asia/Manila')::date = d),
      'discount', (select coalesce(sum(b.discount + b.vat_removed), 0) from bills b where (b.closed_at at time zone 'Asia/Manila')::date = d),
      'service_charge', (select coalesce(sum(b.service_charge), 0) from bills b where (b.closed_at at time zone 'Asia/Manila')::date = d),
      'cash', (select coalesce(sum(p.amount), 0) from payments p where p.method = 'cash' and (p.created_at at time zone 'Asia/Manila')::date = d),
      'gcash', (select coalesce(sum(p.amount), 0) from payments p where p.method = 'gcash' and (p.created_at at time zone 'Asia/Manila')::date = d),
      'card', (select coalesce(sum(p.amount), 0) from payments p where p.method = 'card' and (p.created_at at time zone 'Asia/Manila')::date = d))
    into s;
  expected := (s->>'cash')::numeric;
  insert into day_closings (day, expected_cash, counted_cash, difference, summary)
    values (d, expected, counted_cash, counted_cash - expected, s)
    on conflict (day) do update set expected_cash = excluded.expected_cash, counted_cash = excluded.counted_cash,
      difference = excluded.difference, summary = excluded.summary, created_at = now(), created_by = auth.uid()
    returning * into row;
  return to_jsonb(row);
end $$;
revoke execute on function close_day(numeric) from public, anon;
grant execute on function close_day(numeric) to authenticated;

-- ===== v3: sold-out switch, live crab batches, expenses + monthly report (P&L, waste)
-- Sold out "for today": stores the (Manila) date, so it resets by itself the next day.
alter table recipes add column if not exists sold_out_on date;
create or replace function manila_today() returns date language sql stable as $$ select (now() at time zone 'Asia/Manila')::date $$;
create or replace function set_sold_out(recipe_id text, sold_out boolean) returns boolean
language plpgsql security definer set search_path = demo as $$
begin
  if app_role() <> 'owner' then
    raise exception 'Only the owner can mark items sold out';
  end if;
  update recipes r set sold_out_on = case when sold_out then manila_today() end where r.id = set_sold_out.recipe_id;
  if not found then
    raise exception 'Unknown menu item';
  end if;
  return sold_out;
end $$;
revoke execute on function set_sold_out(text, boolean) from public, anon;
grant execute on function set_sold_out(text, boolean) to authenticated;

-- Batch tracking: each purchase of a tracked ingredient is a batch. What's left of each batch is worked
-- out on the page (oldest used first); dead crabs are logged against their batch.
alter table ingredients add column if not exists batch_tracked boolean not null default false;
update ingredients set batch_tracked = true where id = 'crab';
alter table stock_adjustments add column if not exists purchase_id bigint references purchases(id) on delete set null;

create or replace function log_dead(ingredient_id text, purchase_id bigint, qty numeric) returns jsonb
language plpgsql security definer set search_path = demo as $$
declare old_stock numeric; cost numeric;
begin
  if app_role() <> 'owner' then
    raise exception 'Only the owner can log losses';
  end if;
  if qty is null or qty <= 0 then
    raise exception 'Enter how many';
  end if;
  select i.stock into old_stock from ingredients i where i.id = log_dead.ingredient_id for update;
  if old_stock is null then
    raise exception 'Unknown ingredient';
  end if;
  if qty > old_stock then
    raise exception 'That is more than is in stock';
  end if;
  if purchase_id is not null and not exists (select 1 from purchases p where p.id = log_dead.purchase_id and p.ingredient_id = log_dead.ingredient_id) then
    raise exception 'Unknown batch';
  end if;
  select c.cost into cost from ingredient_costs c where c.ingredient_id = log_dead.ingredient_id;
  insert into stock_adjustments (ingredient_id, change, new_stock, reason, old_cost, new_cost, purchase_id)
    values (log_dead.ingredient_id, -qty, old_stock - qty, 'dead', cost, cost, log_dead.purchase_id);
  update ingredients i set stock = old_stock - qty where i.id = log_dead.ingredient_id;
  return jsonb_build_object('stock', old_stock - qty);
end $$;
revoke execute on function log_dead(text, bigint, numeric) from public, anon;
grant execute on function log_dead(text, bigint, numeric) to authenticated;

-- place_order refuses items marked sold out today, and items deleted from the menu
create or replace function reject_sold_out() returns trigger language plpgsql as $$
begin
  if exists (select 1 from recipes r where r.id = new.recipe_id and r.archived_at is not null) then
    raise exception 'is no longer on the menu: %', new.recipe_id;
  end if;
  if exists (select 1 from recipes r where r.id = new.recipe_id and r.sold_out_on = manila_today()) then
    raise exception 'is sold out today: %', new.recipe_id;
  end if;
  return new;
end $$;
-- Deleting a menu item in Portions hides it rather than removing the row, so past orders keep their dish.
alter table recipes add column if not exists archived_at timestamptz;
grant update (archived_at) on recipes to authenticated;  -- owner only, via the "owner edit menu price" policy
drop trigger if exists order_items_sold_out on order_items;
create trigger order_items_sold_out before insert on order_items for each row execute function reject_sold_out();

-- Expenses (rent, wages, gas…) for the monthly profit & loss. Owner only.
create table if not exists expenses (
  id         bigint generated always as identity primary key,
  spent_on   date not null,
  category   text not null check (category in ('rent', 'wages', 'gas', 'electricity', 'water', 'supplies', 'repairs', 'other')),
  amount     numeric not null check (amount > 0),
  note       text check (length(note) <= 120),
  created_at timestamptz not null default now(),
  created_by uuid default auth.uid()
);
alter table expenses enable row level security;
revoke all on expenses from anon, authenticated;
grant select, insert, delete on expenses to authenticated;
create policy "owner read expenses" on expenses for select to authenticated using (app_role() = 'owner');
create policy "owner add expenses" on expenses for insert to authenticated with check (app_role() = 'owner');
create policy "owner remove expenses" on expenses for delete to authenticated using (app_role() = 'owner');

-- Forecast vs guesswork (capstone KPI): the model's forecast of how much of an ingredient a day will use, and the
-- owner/manager's own estimate, both saved before the day starts so they can be compared with what was actually used.
create table if not exists forecasts (
  day           date not null,
  ingredient_id text not null references ingredients(id) on delete cascade,
  model         numeric check (model >= 0),
  staff         numeric check (staff >= 0),
  updated_at    timestamptz not null default now(),
  primary key (day, ingredient_id)
);
alter table forecasts enable row level security;
revoke all on forecasts from anon, authenticated;
grant select on forecasts to authenticated;
create policy "owner read forecasts" on forecasts for select to authenticated using (app_role() = 'owner');
-- rows: [{ingredient_id, model?, staff?}]; a missing value keeps what was saved. Only future days, so nothing is
-- changed after the actual numbers are known.
create or replace function save_forecasts(day date, rows jsonb) returns void
language plpgsql security definer set search_path = demo as $$
begin
  if app_role() <> 'owner' then
    raise exception 'Only the owner can save forecasts';
  end if;
  if day <= manila_today() then
    raise exception 'Forecasts can only be saved for days that have not started';
  end if;
  insert into forecasts (day, ingredient_id, model, staff)
    select save_forecasts.day, x->>'ingredient_id', (x->>'model')::numeric, (x->>'staff')::numeric from jsonb_array_elements(rows) x
  on conflict on constraint forecasts_pkey do update
    set model = coalesce(excluded.model, forecasts.model), staff = coalesce(excluded.staff, forecasts.staff), updated_at = now();
end $$;
revoke execute on function save_forecasts(date, jsonb) from public, anon;
grant execute on function save_forecasts(date, jsonb) to authenticated;

-- Monthly report: sales from paid bills, ingredient cost of what was sold, stock losses (waste and
-- dead crabs; miscounts are left out) valued at the cost at the time, and expenses. Months are Manila calendar months.
create or replace function monthly_report(month date) returns jsonb
language plpgsql security definer set search_path = demo as $$
declare m0 date := date_trunc('month', month)::date; m1 date := (date_trunc('month', month) + interval '1 month')::date; r jsonb;
begin
  if app_role() <> 'owner' then
    raise exception 'Only the owner can see reports';
  end if;
  with b as (select * from bills where (closed_at at time zone 'Asia/Manila')::date >= m0 and (closed_at at time zone 'Asia/Manila')::date < m1),
  sold as (
    select oi.recipe_id, oi.qty, coalesce(c.unit_cost,
             (select coalesce(sum(ri.qty * ic.cost), 0) from recipe_ingredients ri left join ingredient_costs ic on ic.ingredient_id = ri.ingredient_id where ri.recipe_id = oi.recipe_id)) unit_cost
    from orders o join b on b.id = o.bill_id join order_items oi on oi.order_id = o.id
    left join order_item_costs c on c.order_id = oi.order_id and c.recipe_id = oi.recipe_id),
  loss as (
    select a.ingredient_id, i.name, i.unit, a.reason, -a.change qty, -a.change * coalesce(a.old_cost, ic.cost, 0) value
    from stock_adjustments a join ingredients i on i.id = a.ingredient_id left join ingredient_costs ic on ic.ingredient_id = a.ingredient_id
    where a.change < 0 and a.reason in ('waste', 'dead') and (a.created_at at time zone 'Asia/Manila')::date >= m0 and (a.created_at at time zone 'Asia/Manila')::date < m1),
  ex as (select * from expenses where spent_on >= m0 and spent_on < m1)
  select jsonb_build_object(
    'month', m0,
    'bills', (select count(*) from b),
    'gross', (select coalesce(sum(gross), 0) from b),
    'discounts', (select coalesce(sum(vat_removed + discount), 0) from b),
    'service_charge', (select coalesce(sum(service_charge), 0) from b),
    'collected', (select coalesce(sum(total), 0) from b),
    'ingredient_cost', (select coalesce(sum(qty * unit_cost), 0) from sold),
    'losses', (select coalesce(jsonb_agg(jsonb_build_object('ingredient', name, 'unit', unit, 'dead', reason = 'dead', 'qty', q, 'value', v) order by v desc), '[]')
               from (select name, unit, reason = 'dead' as reason_dead, reason, sum(qty) q, sum(value) v from loss group by name, unit, reason) l),
    'loss_value', (select coalesce(sum(value), 0) from loss),
    -- crab KPIs: bought, lost (dead or thrown out, and days held when lost), and used by dishes ordered this month
    'batch', (select coalesce(jsonb_agg(jsonb_build_object('ingredient', i.name, 'unit', i.unit,
        'bought', (select coalesce(sum(p.qty), 0) from purchases p where p.ingredient_id = i.id
                   and (p.created_at at time zone 'Asia/Manila')::date >= m0 and (p.created_at at time zone 'Asia/Manila')::date < m1),
        'dead', (select coalesce(sum(qty), 0) from loss l where l.ingredient_id = i.id),
        'dead_value', (select coalesce(sum(value), 0) from loss l where l.ingredient_id = i.id),
        'dead_by_age', (select coalesce(jsonb_object_agg(age, q), '{}') from (
            select case when p.id is null then 'unknown'  -- least() skips nulls, so test for a missing batch first
                   else least((a.created_at at time zone 'Asia/Manila')::date - (p.created_at at time zone 'Asia/Manila')::date, 4)::text end age, sum(-a.change) q
            from stock_adjustments a left join purchases p on p.id = a.purchase_id
            where a.ingredient_id = i.id and a.reason in ('dead', 'waste') and a.change < 0
              and (a.created_at at time zone 'Asia/Manila')::date >= m0 and (a.created_at at time zone 'Asia/Manila')::date < m1
            group by 1) d),
        'sold', (select coalesce(sum(oi.qty * ri.qty), 0) from orders o join order_items oi on oi.order_id = o.id
                 join recipe_ingredients ri on ri.recipe_id = oi.recipe_id and ri.ingredient_id = i.id
                 where (o.created_at at time zone 'Asia/Manila')::date >= m0 and (o.created_at at time zone 'Asia/Manila')::date < m1)
      ) order by i.name), '[]') from ingredients i where i.batch_tracked),
    -- saved forecasts for finished days this month, with what dishes ordered that day actually used
    'forecasts', (select coalesce(jsonb_agg(jsonb_build_object('day', f.day, 'ingredient_id', f.ingredient_id, 'ingredient', i.name, 'unit', i.unit,
        'model', f.model, 'staff', f.staff,
        'actual', (select coalesce(sum(oi.qty * ri.qty), 0) from orders o join order_items oi on oi.order_id = o.id
                   join recipe_ingredients ri on ri.recipe_id = oi.recipe_id and ri.ingredient_id = f.ingredient_id
                   where (o.created_at at time zone 'Asia/Manila')::date = f.day)
      ) order by f.day), '[]') from forecasts f join ingredients i on i.id = f.ingredient_id
      where f.day >= m0 and f.day < m1 and f.day < manila_today()),
    'expenses', (select coalesce(jsonb_object_agg(category, total), '{}') from (select category, sum(amount) total from ex group by category) e),
    'expense_total', (select coalesce(sum(amount), 0) from ex))
  into r;
  return r;
end $$;
revoke execute on function monthly_report(date) from public, anon;
grant execute on function monthly_report(date) to authenticated;

-- ===== v4: a lowered count is labelled waste or miscount; only waste (and dead crabs) count as losses.
-- A raised count is always a miscount. Price-only edits have no reason.
drop function if exists edit_inventory(text, numeric, numeric, numeric);
create or replace function edit_inventory(ingredient_id text, new_stock numeric, new_cost numeric, new_min numeric default null, reason text default null) returns jsonb
language plpgsql security definer set search_path = demo as $$
declare old_stock numeric; old_cost numeric; why text;
begin
  if app_role() <> 'owner' then
    raise exception 'Only the owner can edit inventory';
  end if;
  if new_stock is null or new_stock < 0 or new_cost is null or new_cost < 0 or new_min < 0 then
    raise exception 'Count, price and low-stock level must be 0 or more';
  end if;
  select i.stock into old_stock from ingredients i where i.id = edit_inventory.ingredient_id for update;
  if old_stock is null then
    raise exception 'Unknown ingredient';
  end if;
  if new_stock < old_stock and (reason is null or reason not in ('waste', 'miscount')) then
    raise exception 'Say whether the drop is waste or a miscount';
  end if;
  why := case when new_stock < old_stock then reason when new_stock > old_stock then 'miscount' end;
  select c.cost into old_cost from ingredient_costs c where c.ingredient_id = edit_inventory.ingredient_id;
  if new_stock <> old_stock or new_cost is distinct from old_cost then
    insert into stock_adjustments (ingredient_id, change, new_stock, reason, old_cost, new_cost)
      values (edit_inventory.ingredient_id, edit_inventory.new_stock - old_stock, edit_inventory.new_stock, why, old_cost, edit_inventory.new_cost);
  end if;
  update ingredients i set stock = edit_inventory.new_stock, min_stock = coalesce(edit_inventory.new_min, i.min_stock)
    where i.id = edit_inventory.ingredient_id;
  insert into ingredient_costs (ingredient_id, cost, estimated) values (edit_inventory.ingredient_id, edit_inventory.new_cost, false)
    on conflict on constraint ingredient_costs_pkey do update set cost = excluded.cost, estimated = false;
  return jsonb_build_object('stock', new_stock, 'cost', new_cost, 'min_stock', (select min_stock from ingredients where id = edit_inventory.ingredient_id));
end $$;
revoke execute on function edit_inventory(text, numeric, numeric, numeric, text) from public, anon;
grant execute on function edit_inventory(text, numeric, numeric, numeric, text) to authenticated;

-- ===== v5: a lowered count from the pencil is always waste. Miscounts are fixed by editing the purchase
-- in Purchase history, which moves stock by the difference and re-blends the average price.
drop function if exists edit_inventory(text, numeric, numeric, numeric, text);
create or replace function edit_inventory(ingredient_id text, new_stock numeric, new_cost numeric, new_min numeric default null) returns jsonb
language plpgsql security definer set search_path = demo as $$
declare old_stock numeric; old_cost numeric;
begin
  if app_role() <> 'owner' then
    raise exception 'Only the owner can edit inventory';
  end if;
  if new_stock is null or new_stock < 0 or new_cost is null or new_cost < 0 or new_min < 0 then
    raise exception 'Count, price and low-stock level must be 0 or more';
  end if;
  select i.stock into old_stock from ingredients i where i.id = edit_inventory.ingredient_id for update;
  if old_stock is null then
    raise exception 'Unknown ingredient';
  end if;
  select c.cost into old_cost from ingredient_costs c where c.ingredient_id = edit_inventory.ingredient_id;
  if new_stock <> old_stock or new_cost is distinct from old_cost then
    insert into stock_adjustments (ingredient_id, change, new_stock, reason, old_cost, new_cost)
      values (edit_inventory.ingredient_id, edit_inventory.new_stock - old_stock, edit_inventory.new_stock,
              case when new_stock < old_stock then 'waste' when new_stock > old_stock then 'miscount' end, old_cost, edit_inventory.new_cost);
  end if;
  update ingredients i set stock = edit_inventory.new_stock, min_stock = coalesce(edit_inventory.new_min, i.min_stock)
    where i.id = edit_inventory.ingredient_id;
  insert into ingredient_costs (ingredient_id, cost, estimated) values (edit_inventory.ingredient_id, edit_inventory.new_cost, false)
    on conflict on constraint ingredient_costs_pkey do update set cost = excluded.cost, estimated = false;
  return jsonb_build_object('stock', new_stock, 'cost', new_cost, 'min_stock', (select min_stock from ingredients where id = edit_inventory.ingredient_id));
end $$;
revoke execute on function edit_inventory(text, numeric, numeric, numeric) from public, anon;
grant execute on function edit_inventory(text, numeric, numeric, numeric) to authenticated;

-- Fix a purchase's amount or total paid. Stock moves by the amount difference; the average price is
-- re-blended as if the purchase had been entered right (value on hand + paid difference) / new stock.
create or replace function edit_purchase(purchase_id bigint, qty numeric, total_cost numeric) returns jsonb
language plpgsql security definer set search_path = demo as $$
declare p purchases; old_stock numeric; old_cost numeric; new_stock numeric; avg_cost numeric;
begin
  if app_role() <> 'owner' then
    raise exception 'Only the owner can edit purchases';
  end if;
  if qty is null or qty <= 0 or total_cost is null or total_cost < 0 then
    raise exception 'Amount must be above 0 and cost 0 or more';
  end if;
  select * into p from purchases where id = edit_purchase.purchase_id for update;
  if p.id is null then
    raise exception 'Unknown purchase';
  end if;
  select i.stock into old_stock from ingredients i where i.id = p.ingredient_id for update;
  new_stock := old_stock + qty - p.qty;
  if new_stock < 0 then
    raise exception 'That would leave less than 0 in stock';
  end if;
  select coalesce(c.cost, 0) into old_cost from ingredient_costs c where c.ingredient_id = p.ingredient_id;
  avg_cost := case when new_stock > 0
    then greatest(0, (greatest(old_stock, 0) * coalesce(old_cost, 0) + total_cost - p.total_cost) / new_stock)
    else coalesce(old_cost, 0) end;
  update purchases set qty = edit_purchase.qty, total_cost = edit_purchase.total_cost where id = p.id;
  update ingredients i set stock = new_stock where i.id = p.ingredient_id;
  insert into ingredient_costs (ingredient_id, cost, estimated) values (p.ingredient_id, avg_cost, false)
    on conflict on constraint ingredient_costs_pkey do update set cost = excluded.cost, estimated = false;
  insert into stock_adjustments (ingredient_id, change, new_stock, reason, old_cost, new_cost, purchase_id)
    values (p.ingredient_id, qty - p.qty, new_stock, 'miscount', old_cost, avg_cost, p.id);
  return jsonb_build_object('stock', new_stock, 'cost', avg_cost);
end $$;
revoke execute on function edit_purchase(bigint, numeric, numeric) from public, anon;
grant execute on function edit_purchase(bigint, numeric, numeric) to authenticated;

-- ===== v6: delete a purchase entered by mistake. Stock drops by its amount and the average price is
-- re-blended without it, the same way edit_purchase does. Logged as a miscount (not waste).
create or replace function delete_purchase(purchase_id bigint) returns jsonb
language plpgsql security definer set search_path = demo as $$
declare p purchases; old_stock numeric; old_cost numeric; new_stock numeric; avg_cost numeric;
begin
  if app_role() <> 'owner' then
    raise exception 'Only the owner can delete purchases';
  end if;
  select * into p from purchases where id = delete_purchase.purchase_id for update;
  if p.id is null then
    raise exception 'Unknown purchase';
  end if;
  select i.stock into old_stock from ingredients i where i.id = p.ingredient_id for update;
  new_stock := old_stock - p.qty;
  if new_stock < 0 then
    raise exception 'That would leave less than 0 in stock';
  end if;
  select coalesce(c.cost, 0) into old_cost from ingredient_costs c where c.ingredient_id = p.ingredient_id;
  avg_cost := case when new_stock > 0
    then greatest(0, (greatest(old_stock, 0) * coalesce(old_cost, 0) - p.total_cost) / new_stock)
    else coalesce(old_cost, 0) end;
  insert into stock_adjustments (ingredient_id, change, new_stock, reason, old_cost, new_cost)
    values (p.ingredient_id, -p.qty, new_stock, 'miscount', old_cost, avg_cost);
  delete from purchases where id = p.id;
  update ingredients i set stock = new_stock where i.id = p.ingredient_id;
  insert into ingredient_costs (ingredient_id, cost, estimated) values (p.ingredient_id, avg_cost, false)
    on conflict on constraint ingredient_costs_pkey do update set cost = excluded.cost, estimated = false;
  return jsonb_build_object('stock', new_stock, 'cost', avg_cost);
end $$;
revoke execute on function delete_purchase(bigint) from public, anon;
grant execute on function delete_purchase(bigint) to authenticated;


-- the current menu, recipes and costs instead of supabase.sql's starter menu
delete from demo.recipe_ingredients; delete from demo.ingredient_costs; delete from demo.recipes; delete from demo.ingredients;
insert into demo.ingredients (id, name, unit, stock, min_stock, batch_tracked) select id, name, unit, 0, 0, batch_tracked from public.ingredients;
insert into demo.recipes (id, name, category, price, pricing, archived_at) select id, name, category, price, pricing, archived_at from public.recipes;
insert into demo.recipe_ingredients (recipe_id, ingredient_id, qty) select recipe_id, ingredient_id, qty from public.recipe_ingredients;
insert into demo.ingredient_costs (ingredient_id, cost, estimated) select ingredient_id, cost, estimated from public.ingredient_costs;

